window.kbPageData["views/practice/s-c94c813ed743298a"] = {"key":"practice/s-c94c813ed743298a","state":{"route":"practice/s-c94c813ed743298a"},"tree":"<a data-toc-link href=\"#skills/shenlun\">申论技能首页</a><details data-branch=\"module-归纳概括\" open><summary>归纳概括</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-c898afc5816920c2\">概括作用与成效</a><a data-toc-link href=\"#practice/s-0b47c7faa1dcfbc7\">提炼做法与经验</a><a data-toc-link href=\"#practice/s-75a1eb1e46268fd8\">归类概括材料中的问题</a><a data-toc-link href=\"#practice/s-4863baf2b4febcf4\">配对概括做法与成效</a><a data-toc-link href=\"#practice/s-c94c813ed743298a\" aria-current=\"page\">从材料提取概念特征</a><a data-toc-link href=\"#practice/s-4da331cba0998f2b\">分条梳理不同立场与分歧</a></div></details><details data-branch=\"module-综合分析\"><summary>综合分析</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-43e39afd29a17e74\">解释含义与作用</a><a data-toc-link href=\"#practice/s-599008555ed60dda\">分析现象形成的原因</a><a data-toc-link href=\"#practice/s-93367fee5c934df6\">从案例推导改进建议</a></div></details><details data-branch=\"module-提出对策\"><summary>提出对策</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-c6bd983baf5dd3ae\">根据问题成因逐项提出措施</a><a data-toc-link href=\"#practice/s-ecba3f8c2c1d3b9b\">将外地经验转化为本地措施</a><a data-toc-link href=\"#practice/s-9b570af6b9f113ee\">按治理环节组织对策</a><a data-toc-link href=\"#practice/s-91888cb77ec12615\">从材料反馈中提炼改进建议</a></div></details><details data-branch=\"module-应用文写作\"><summary>应用文写作</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-171ebed39b4fe1cf\">汇报与交流发言</a><a data-toc-link href=\"#practice/s-b92b682e65d12042\">面向公众动员参与</a><a data-toc-link href=\"#practice/s-cabc6af5d656b214\">宣传介绍与活动报道</a><a data-toc-link href=\"#practice/s-5cd530a611f08110\">编写案例摘要</a><a data-toc-link href=\"#practice/s-9f175b7eb1a79028\">陈述事由与请求</a><a data-toc-link href=\"#practice/s-38dece0b54a49be3\">拟定工作事项与措施</a><a data-toc-link href=\"#practice/s-c8dfde3ede3eadab\">撰写案例短评或点评</a></div></details><details data-branch=\"module-文章写作\"><summary>文章写作</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-b8139af04b609dce\">展开分论点的论证</a><a data-toc-link href=\"#practice/s-4fdadcb77809c673\">围绕中心论点组织分论点</a><a data-toc-link href=\"#practice/s-ab43045e4cab9ffe\">从材料立意并确立中心论点</a></div></details>","packs":{"国考 2025 副省级 申论#1":"f6b08578b20929f4bdf0e994"},"questions":{"国考 2025 副省级 申论#1":{"paper":"国考 2025 副省级 申论","n":1,"mod":"申论","src":["7543a550935cd0cc16be.pdf",4],"asrc":["3f81b5d39fbc5b1d205d.pdf",1]}},"first":{"qs":{"国考 2025 副省级 申论#1":{"paper":"国考 2025 副省级 申论","n":1,"mod":"申论","src":["7543a550935cd0cc16be.pdf",4],"asrc":["3f81b5d39fbc5b1d205d.pdf",1],"m":["6e653528d184d60f"],"task":"根据给定资料1，在350字以内界定三条“黄河”，说明它们如何通过监测预警、模拟推演和实体试验协同服务黄河治理。","current_affairs":{"state":"否","event":null,"year":null,"basis":"作答依据是材料提供的三条“黄河”的含义及协同实践，2024年兰州考察讲话仅作治理背景。"},"links":[{"id":"k-ce6e5741dbc3711e","label":"数字孪生黄河的虚实交互与同步仿真","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"M1","quote":"实现与原型黄河的同步仿真运行、虚实交互、迭代优化。","why":"作答需要说明数字孪生黄河以实体黄河为原型，通过计算机模型实现同步仿真和虚实交互。","origin":"逐题标记"},{"id":"k-e56d4f9b5d46ab99","label":"模型黄河的实体模型试验","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"模型黄河指把黄河放进实验室，开展各类模型试验。","why":"作答需要说明模型黄河指在实验室以实体模型再现黄河相关过程并开展试验。","origin":"逐题标记"},{"id":"k-2b01bdf0bdadd547","label":"原型黄河、数字孪生黄河和模型黄河的协同治理机制","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"原型黄河是数字孪生黄河和模型黄河的基础。","why":"作答需要解释两类模型如何以实体黄河为基础，分别通过预报、预警、预演、预案和实体试验所得的物理参数支撑实际治理。","origin":"逐题标记"},{"id":"s-c94c813ed743298a","label":"从材料中提取指定对象的定义特征","catalog_id":null,"type":null,"role":"解题依据","field":"question","quote":"这三条“黄河”分别指的是什么","why":"需要从分散的材料段落定位三个对象，并按各自的实体或模型形态概括含义。","origin":"逐题标记"},{"id":"s-43e39afd29a17e74","label":"按对象分工和作用链条归纳协同机制","catalog_id":null,"type":null,"role":"解题依据","field":"question","quote":"说明它们是如何协同发挥作用的。","why":"需要把监测感知、仿真推演和实体试验等事例按对象归组，并说明各自的成果怎样用于实际治理。","origin":"逐题标记","originalId":"s-3e40edb924de83d6"}],"stem":"“给定资料1”提到了三条“黄河”，请你谈谈这三条“黄河”分别指的是什么，并说明它们是如何协同发挥作用的。\n（15分）\n要求：全面、准确、有条理。不超过350字。","options":[],"answer":"","analysis":"一、三条黄河：1.原型黄河。2.数字孪生黄河指把原型黄河装进计算机，同步仿真运行、虚实交互、迭代优化。\n3.模型黄河指把黄河放进实验室，开展各类模型试验。\n   二、关系：1.原型黄河是数字孪生黄河和模型黄河的基础。2.数字孪生黄河为原型黄河治理提供预报、预警、预\n演、预案。3.模型黄河为原型黄河治理提供物理参数，给予支撑引领。\n   三、如何协同：1.打造“2+N”智能业务应用体系。建设防汛会商预演系统，防汛各环节一屏掌控，五级联防联\n动、“四预”过程管理；构建监测感知网络，获取动态数据；打造河务通App，汇集海量数据；开展远程巡航监测，发\n现、处置和预防违法行为。2.打造试验基地。建成一批基础科研设施；形成黄河模型架构体系；建设特色人工智能模\n型和可视化模型，构筑黄河水利模拟系统和知识模型；自主研发多种模型于一体、安全可控的模型平台。\n  参考答案说明：本参考答案从三条“黄河”的释义、三者间的关系、发挥协同作用的方式三个角度展开。其中，释\n义部分指出三条“黄河”分别指原型黄河、数字孪生黄河和模型黄河；三者关系分别对三条“黄河”间相互作用的关系进\n行了阐述；发挥协同作用的方式分别从“打造‘2+N’智能业务应用体系”和“打造实验基地”两个方面展开。各条答案要点\n之间在内容上相互并列，没有交叉。","figs":[],"state":"已标记","notes":[],"domains":["科技","生态环境"],"nature":"综合题","current":false}},"materialFiles":{"6e653528d184d60f":"1188f0c9dcdbff7515b77197"},"terms":{"k-ce6e5741dbc3711e":{"id":"k-ce6e5741dbc3711e","mode":"k","type":"概念与词义","title":"数字孪生黄河","qs":[],"count":1},"k-e56d4f9b5d46ab99":{"id":"k-e56d4f9b5d46ab99","mode":"k","type":"概念与词义","title":"模型黄河","qs":[],"count":1},"k-2b01bdf0bdadd547":{"id":"k-2b01bdf0bdadd547","mode":"k","type":"原理与机制","title":"三条“黄河”协同治理","qs":[],"count":1},"s-c94c813ed743298a":{"id":"s-c94c813ed743298a","mode":"s","type":"归纳概括","title":"从材料提取概念特征","qs":[],"count":1},"s-43e39afd29a17e74":{"id":"s-43e39afd29a17e74","mode":"s","type":"综合分析","title":"解释含义与作用","qs":[],"count":6}},"questions":{}},"firstMaterials":[{"key":"6e653528d184d60f","value":["材料1","材料1\n  黄河奔腾生生不息，科技活水澎湃成潮。进入新的发展阶段，信息技术不断迭代升级，各种科技实践也正一幕\n幕上演，为黄河保护治理赋予新解。\n  “我手中这个设备俗称‘智慧石头’，它由智能芯片和电池组成。把它放到防洪堤坝根石堆里，它就成了打入根石堆\n的一个小小‘侦察员’，能够24小时全天候实时预警。”智慧黄河研究院赵工程师介绍说，“如果根石发生位移，它会自\n动抓拍并发出报警信号，一线巡查人员就能及时赶到现场处置险情。”\n  其实，“智慧石头”只是数字孪生黄河建设的一个基础应用。2022年水利部黄河水利委员会发布的《数字孪生黄河\n建设规划（2022—2025）》提出，要加快构建具有预报、预警、预演、预案（“四预”）功能的数字孪生黄河。数字\n孪生黄河，就是把实体的原型黄河“装进”计算机，实现与原型黄河的同步仿真运行、虚实交互、迭代优化。近年来，\n黄河水利委员会以流域防洪、水资源管理为建设重点，开展水工程安全、淤地坝、河湖管理保护等业务应用系统建\n设，初步形成了“2+N”智能业务应用体系。\n  走进黄河防汛值班室，大屏幕上，一条被“复刻”至计算机的“黄河”滔滔奔涌，清晰演示着洪水演进、滩区灾情损\n失情况，工作人员犹如置身黄河岸边，在“云端”研判和商定调度方案。这个防汛会商预演系统，让防汛监测、感知、\n巡查、指挥等环节一屏掌控，实现省、市、县、班、点五级联防联动和“四预”模拟推演的过程管理。\n  “在数字孪生黄河里模拟一场洪水的发生，观察洪水对工程哪些部分造成了冲击，据此再对实体的原型黄河相应\n工程进行防范或者处置。”数字孪生黄河建设负责人介绍说，“在这个过程中，构建智能高效的监测感知网络，获取原\n型黄河的动态数据，是基础，也是关键。”\n  “你看，现在有2200人在线，85个工程靠河，158人进行了现场巡查，上报了309个巡查日志。”河南河务局数字\n办负责人打开河务通App后介绍说。据了解，这个将监测感知系统、应用支撑系统、业务应用系统的海量数据汇集于\n手机端的河务通App，已经成为河南河务局工作人员巡河使用的日常工具。\n  “叮咚！”收到河务通App的预警提醒，值班员小军马上打开手机查看：“系统识别出管理A段以北疑似有较大漂浮\n物在移动。”小军立即启动无人机复核现场，再将复核后的信息上传平台，通过系列程序就完成了一次工程险情处\n置。\n  据小军介绍，远程巡航监测能及时发现并处置河道管理范围内的水事违法行为，还能对灌区引水情况开展巡\n查，督查计量设施及水量计量情况，预防出现无计量取水、无证取水及擅自改变取水用途等违法行为，提高了灌区\n取用水监查和河道管理的效率。\n  “模型黄河”试验基地隶属于黄河水利科学研究院，已经成为科技治黄的闪亮名片。经过30多年发展，该基地已建\n成水土流失试验厅、水库试验厅、下游河道试验厅、黄河口试验厅以及基础研究试验厅、水工试验厅、抗震实验\n室、抗磨实验室、综合实验楼等一批基础科研设施，为洪水防御、重大水利工程建设论证、河道整治、河口治理、\n水工程调度和水沙运动及河床演变规律探索等提供物理参数，发挥支撑与引领作用。\n  “模型黄河”就是把黄河“放进”实验室。比如，利用“模型黄河”开展洪水预演实体模型试验，为黄河防汛决策指挥\n和调整防洪部署提供重要技术支撑；利用水土流失试验厅，开展典型黄土丘陵区坡面水流侵蚀产沙的动力学机理模\n拟试验，为坡面水土保持措施优化配置提供理论依据；利用小浪底库区试验厅，开展小浪底水库淤积形态优选与调\n控试验，为小浪底水库优化运行找寻方案。此外，黄河水利科学研究院自主研发的河工模型人工智能地形制作设\n备，可实现高精度、高分辨率、大场景复杂模型三维地形的快速制作；用水需求及水资源配置模型，能够精准预测\n黄河流域灌区未来10天至15天的引黄灌溉需水量等等。\n  据介绍，黄河水利委员会现已基本形成水文预报、工程调度、灾情评估、冰凌预报、河口治理等拥有自主知识\n产权的黄河模型架构体系，同时开展流域特色人工智能模型和可视化模型建设，构筑基于云服务的黄河水利模拟系\n统和知识模型，自主研发了耦合水文、水动力、冰凌等多种模型于一体、安全可控的模型平台，为流域统一治理提\n供了坚实支撑。\n  “黄河很美，将来会更美。”2024年9月，习近平总书记在甘肃省兰州市考察黄河时指出，要更加突出黄河治理的\n系统性、整体性、协同性，推动构建上下游贯通一体的生态环境治理体系，深入实施重要生态系统保护和修复重大\n工程，提升流域生态系统稳定性。\n  运用科技让三条“黄河”协同关联，已经成为保障黄河安澜的重要手段，有力推动了沿黄人民生命财产安全防线的\n构筑。",["7543a550935cd0cc16be.pdf",1]],"label":"国考 2025 副省级 申论|材料1"}],"node":{"id":"s-c94c813ed743298a","mode":"s","title":"从材料提取概念特征","type":"归纳概括","domain":"科技","reading":"","intro":"","priority":100,"aliases":["从材料中提取指定对象的定义特征"],"qs":["国考 2025 副省级 申论#1"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"subject":"申论","publishedSets":[{"name":"从材料提取概念特征","ids":["国考 2025 副省级 申论#1"],"units":[["国考 2025 副省级 申论#1"]]}]}};
